run:
() => {
      const K = window.kirkpinar, G = K.G, BOUTS = 12;
      const rng = (a) => () => { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
      const click = (sel) => { const b = document.querySelector(sel); if (!b) throw new Error(`gate: ${sel} missing on screen ${G.screen}`); b.click(); };
      const out = { bouts: 0, wins: 0, losses: 0, ptsFor: 0, ptsAgainst: 0, boutSec: 0 };
      click('#bPlay');
      for (let i = 0; i < BOUTS && G.screen !== 'ending'; i++) {
        if (G.screen === 'ladder') click('[data-act="ladderGo"]');
        Math.random = rng(1000 + i);
        click('[data-act="vsGo"]');
        window.kirkpinarSim(600); // returns the requested time, not the bout's; M.total is the bout's clock
        const M = G.match;
        if (M.phase !== 'over' || !M.result) throw new Error(`gate: bout ${i + 1} did not end (phase ${M.phase})`);
        out.bouts++; if (M.result.winner === 0) out.wins++; else out.losses++;
        out.ptsFor += M.f[0].score; out.ptsAgainst += M.f[1].score; out.boutSec += M.total;
        click('#resultBox [data-act="ending"], #resultBox [data-act="nextmatch"], #resultBox [data-act="retry"]');
      }
      const run = K.store.run, rungs = [3, 3, 4, 4, 4];
      out.rung = G.screen === 'ending' || !run ? 18 : rungs.slice(0, run.ci).reduce((x, y) => x + y, 0) + run.oi; // ladder rungs won (18 = belt)
      out.boutSec = Math.round(out.boutSec);
      window.__gateM = out;
    }
